"use client";

import * as React from "react";
import { fieldConfig, ZodProvider } from "@autoform/zod";
import * as z from "zod";

import { AutoForm } from "@/components/ui/autoform/tanstack-form";
import {
  ColorPickerField,
  DatePickerField,
  FileUploadField,
  NumberStepperField,
  RadioCardField,
  SliderField,
} from "@/components/tanstack-custom-field-components";
import { ArrayTableWrapper } from "@/components/tanstack-array-table-wrapper";

const schema = z.object({
  quantity: z
    .number()
    .min(1)
    .max(99)
    .default(1)
    .describe("Quantity")
    .check(fieldConfig({ fieldType: "numberStepper" })),

  themeColor: z
    .string()
    .regex(/^#[0-9a-fA-F]{6}$/, "Pick a valid color")
    .default("#6366f1")
    .describe("Find the color")
    .check(fieldConfig({ fieldType: "colorPicker" })),

  birthdate: z
    .string()
    .min(1, "Pick a date")
    .describe("Birthdate")
    .check(fieldConfig({ fieldType: "dateTime" })),

  avatar: z
    .instanceof(File)
    .optional()
    .describe("Profile picture")
    .check(fieldConfig({ fieldType: "fileUpload" })),

  volume: z
    .number()
    .min(0)
    .max(100)
    .default(50)
    .check(fieldConfig({ fieldType: "slider" })),

  plan: z
    .enum(["starter", "pro", "enterprise"])
    .default("starter")
    .describe("Plan")
    .check(
      fieldConfig({
        fieldType: "radioCard",
        customData: {
          options: [
            { id: "starter", label: "Starter", desc: "Up to 3 projects" },
            { id: "pro", label: "Pro", desc: "Up to 100 projects" },
            { id: "enterprise", label: "Enterprise", desc: "Custom limits" },
          ],
        },
      }),
    ),

  services: z
    .array(
      z.object({
        service: z
          .string({ error: "Name the service" })
          .min(1, "Name the service")
          .describe("Service"),
        tier: z
          .enum(["Hobby", "Pro", "Enterprise"])
          .default("Hobby")
          .describe("Tier"),
        created: z.iso
          .date({ error: "Pick a date" })
          .describe("Created")
          .check(fieldConfig({ fieldType: "date" })),
        live: z.boolean().default(false).describe("Live"),
      }),
    )
    .min(1, "Add at least one service")
    .default([
      { service: "GitHub", tier: "Pro", created: "2026-11-02", live: true },
      {
        service: "Database",
        tier: "Enterprise",
        created: "2026-11-05",
        live: true,
      },
      { service: "VPS", tier: "Hobby", created: "2026-11-09", live: false },
      { service: "Sandbox", tier: "Hobby", created: "2026-11-12", live: true },
    ])
    .describe("Services")
    .check(fieldConfig({ arrayWrapper: ArrayTableWrapper })),
});

const schemaProvider = new ZodProvider(schema);

type FormValues = z.infer<typeof schema>;

export function TanStackCustomFieldsDemo() {
  const [result, setResult] = React.useState<FormValues | null>(null);

  return (
    <div className="space-y-6 rounded-lg border bg-background p-6">
      <AutoForm
        schema={schemaProvider}
        formComponents={{
          numberStepper: NumberStepperField,
          radioCard: RadioCardField,
          dateTime: DatePickerField,
          slider: SliderField,
          colorPicker: ColorPickerField,
          fileUpload: FileUploadField,
        }}
        formProps={{ className: "flex flex-col gap-6" }}
        onSubmit={(data) => setResult(data)}
        withSubmit
      />

      <div className="rounded-md border bg-secondary/50 p-4 text-sm">
        <div className="mb-2 font-medium">Submitted value</div>
        <pre className="overflow-auto text-xs">
          {result
            ? JSON.stringify(
                {
                  quantity: result.quantity,
                  plan: result.plan,
                  birthdate: result.birthdate,
                  volume: result.volume,
                  themeColor: result.themeColor,
                  avatar: result.avatar?.name ?? null,
                  services: result.services,
                },
                null,
                2,
              )
            : "null"}
        </pre>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import * as RadioGroupPrimitive from "@radix-ui/react-radio-group";
import { CalendarIcon, CircleIcon, Minus, Plus } from "lucide-react";
import { format } from "date-fns";
import type { AutoFormFieldProps } from "@autoform/react";
import { useFieldContext } from "@autoform/react/tanstack-form";

import { Button } from "@/components/ui/button";
import { Calendar } from "@/components/ui/calendar";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { cn } from "@/lib/utils";

export function NumberStepperField({
  id,
  inputProps,
  error,
}: AutoFormFieldProps) {
  const field = useFieldContext<number>();
  const value = typeof field.state.value === "number" ? field.state.value : 1;

  const step = (delta: number) => {
    field.handleChange(Math.min(99, Math.max(1, value + delta)));
  };

  return (
    <div
      className={cn(
        "flex h-9 w-36 items-center overflow-hidden rounded-lg border border-input shadow-xs transition-shadow focus-within:border-ring focus-within:ring-[3px] focus-within:ring-ring/20",
        error && "border-destructive",
      )}
    >
      <Button
        type="button"
        onClick={() => step(-1)}
        variant="ghost"
        size="sm"
        className="h-full rounded-none rounded-l-lg border-r px-2"
        aria-label="Decrease"
      >
        <Minus className="h-3.5 w-3.5" />
      </Button>
      <Input
        id={id}
        type="number"
        {...inputProps}
        value={value}
        onBlur={field.handleBlur}
        onChange={(event) => field.handleChange(Number(event.target.value))}
        className="h-full w-full rounded-none border-0 text-center shadow-none focus-visible:ring-0 [appearance:textfield] [&::-webkit-inner-spin-button]:appearance-none [&::-webkit-outer-spin-button]:appearance-none"
      />
      <Button
        type="button"
        onClick={() => step(1)}
        variant="ghost"
        size="sm"
        className="h-full rounded-none rounded-r-lg border-l px-2"
        aria-label="Increase"
      >
        <Plus className="h-3.5 w-3.5" />
      </Button>
    </div>
  );
}

type RadioOption = { id: string; label: string; desc?: string };

export function RadioCardField({ id, error, parsedField }: AutoFormFieldProps) {
  const field = useFieldContext<string>();
  const value = typeof field.state.value === "string" ? field.state.value : "";

  const options: RadioOption[] =
    (parsedField.fieldConfig?.customData?.options as
      | RadioOption[]
      | undefined) ??
    (parsedField.options ?? []).map(([id, label]) => ({ id, label }));

  return (
    <RadioGroupPrimitive.Root
      value={value}
      onValueChange={field.handleChange}
      className="flex flex-col gap-1.5"
    >
      {options.map((opt, i) => (
        <Label
          key={opt.id}
          htmlFor={`${id}-${i}`}
          className={cn(
            "flex cursor-pointer items-center gap-2.5 rounded-md border border-input bg-background px-3 py-2 shadow-xs transition-colors has-data-[state=checked]:border-ring/60 has-data-[state=checked]:bg-accent/40",
            error && "border-destructive",
          )}
        >
          <RadioGroupPrimitive.Item
            id={`${id}-${i}`}
            value={opt.id}
            className="aspect-square size-3.5 shrink-0 rounded-full border border-input outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"
          >
            <RadioGroupPrimitive.Indicator className="relative flex items-center justify-center">
              <CircleIcon className="absolute left-1/2 top-1/2 size-1.5 -translate-x-1/2 -translate-y-1/2 fill-primary" />
            </RadioGroupPrimitive.Indicator>
          </RadioGroupPrimitive.Item>
          <div className="flex flex-col gap-1 p-1">
            <span className="text-sm font-medium leading-none">
              {opt.label}
            </span>
            {opt.desc && (
              <span className="mt-0.5 text-xs text-muted-foreground">
                {opt.desc}
              </span>
            )}
          </div>
        </Label>
      ))}
    </RadioGroupPrimitive.Root>
  );
}

export function DatePickerField({ id, error, inputProps }: AutoFormFieldProps) {
  const field = useFieldContext<string>();
  const [open, setOpen] = React.useState(false);
  const dateValue = field.state.value
    ? new Date(`${field.state.value}T00:00:00`)
    : undefined;

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          id={id}
          type="button"
          variant="outline"
          className={cn(
            "w-full justify-start text-left font-normal",
            !dateValue && "text-muted-foreground",
            error && "border-destructive",
          )}
          onBlur={field.handleBlur}
          {...inputProps}
        >
          <CalendarIcon className="mr-2 h-4 w-4" />
          {dateValue ? format(dateValue, "PPP") : "Pick a date"}
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-auto p-0" align="start">
        <Calendar
          mode="single"
          selected={dateValue}
          onSelect={(day) => {
            field.handleChange(day ? format(day, "yyyy-MM-dd") : "");
            setOpen(false);
          }}
          captionLayout="dropdown"
          startMonth={new Date(1900, 0)}
          endMonth={new Date(new Date().getFullYear() + 1, 11)}
          autoFocus
        />
      </PopoverContent>
    </Popover>
  );
}

export function SliderField({ id, inputProps }: AutoFormFieldProps) {
  const field = useFieldContext<number>();
  const value = typeof field.state.value === "number" ? field.state.value : 50;

  return (
    <div className="flex items-center gap-3">
      <input
        id={id}
        type="range"
        min={0}
        max={100}
        step={1}
        value={value}
        onBlur={field.handleBlur}
        onChange={(event) => field.handleChange(Number(event.target.value))}
        className="w-full accent-primary"
        {...inputProps}
      />
      <span className="w-8 text-right text-sm tabular-nums">{value}</span>
    </div>
  );
}

export function ColorPickerField({ id, inputProps }: AutoFormFieldProps) {
  const field = useFieldContext<string>();
  const color =
    typeof field.state.value === "string" ? field.state.value : "#6366f1";

  return (
    <div className="flex items-center gap-3">
      <img
        src="https://autoform.vantezzen.io/banana.png"
        alt="Banana"
        className="h-24 w-24 rounded-md border border-input object-cover"
      />
      <input
        id={id}
        type="color"
        value={color}
        onBlur={field.handleBlur}
        onChange={(event) => field.handleChange(event.target.value)}
        className="h-9 w-14 cursor-pointer rounded border p-0.5"
        {...inputProps}
      />
      <span className="text-sm text-muted-foreground">{color}</span>
    </div>
  );
}

export function FileUploadField({ id }: AutoFormFieldProps) {
  const field = useFieldContext<File | undefined>();
  const file = field.state.value;

  return (
    <div className="flex flex-col gap-1">
      <input
        id={id}
        type="file"
        accept="image/*"
        className="block w-full cursor-pointer rounded border border-input bg-background text-sm file:mr-3 file:border-0 file:bg-secondary file:px-3 file:py-1.5 file:text-sm"
        onBlur={field.handleBlur}
        onChange={(event) => field.handleChange(event.target.files?.[0])}
      />
      {file && (
        <p className="text-xs text-muted-foreground">
          Selected: {file.name} ({(file.size / 1024).toFixed(1)} KB)
        </p>
      )}
    </div>
  );
}

"use client";
// Keep in sync with array-table-wrapper.tsx (the React Hook Form version).

import { getLabel, type ParsedField } from "@autoform/core";
import type {
  ArrayElementWrapperProps,
  ArrayWrapperProps,
  AutoFormFieldProps,
} from "@autoform/react";
import {
  fieldContext,
  formatTanStackPath,
  getErrorMessage,
  useAutoForm,
  useFieldContext,
} from "@autoform/react/tanstack-form";
import { useField } from "@tanstack/react-form";
import { Plus, Trash2 } from "lucide-react";
import * as React from "react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

// ── Helpers ──────────────────────────────────────────────────────────────────

type Cell = { row: number; column: number };

/** Focusable controls a cell editor may render (input, select trigger, …). */
const EDITOR_SELECTOR =
  "input:not([type='hidden']):not(:disabled), textarea:not(:disabled), button:not(:disabled), [role='combobox']";

const ARROW_MOVES: Record<string, [row: number, column: number]> = {
  ArrowUp: [-1, 0],
  ArrowDown: [1, 0],
  ArrowLeft: [0, -1],
  ArrowRight: [0, 1],
};

const isPrintableKey = (event: React.KeyboardEvent) =>
  event.key.length === 1 && !event.altKey && !event.ctrlKey && !event.metaKey;

const isSameCell = (a: Cell | null, b: Cell) =>
  a?.row === b.row && a.column === b.column;

/** A field's label as plain text, for aria attributes. */
const labelText = (field: ParsedField) => {
  const label = getLabel(field);
  return typeof label === "string" ? label : field.key;
};

/** Next cell for Tab / Shift+Tab, wrapping across rows. */
function tabTarget(cell: Cell, rows: number, columns: number, back: boolean) {
  const index = cell.row * columns + cell.column + (back ? -1 : 1);
  if (index < 0 || index >= rows * columns) return null;
  return { row: Math.floor(index / columns), column: index % columns };
}

/**
 * Replaces an input's value as if the user typed `character`. React tracks
 * input values internally, so the native setter is needed for onChange to fire.
 * Number and date inputs reject some characters; those leave the value as is.
 */
function typeInto(editor: HTMLElement, character: string) {
  if (!(editor instanceof HTMLInputElement) || editor.type === "checkbox")
    return;
  const setValue = Object.getOwnPropertyDescriptor(
    HTMLInputElement.prototype,
    "value",
  )?.set;
  const previous = editor.value;
  setValue?.call(editor, character);
  if (editor.value !== character) return setValue?.call(editor, previous);
  editor.dispatchEvent(new Event("input", { bubbles: true }));
}

/** Strips the AutoForm controls' own borders so each cell looks flush. */
const GRID_STYLES = [
  // Editor wrapper fills the cell.
  "[&_[data-grid-editor]]:flex [&_[data-grid-editor]]:h-9 [&_[data-grid-editor]]:items-center",
  "[&_[data-grid-editor]>div]:h-full [&_[data-grid-editor]>div]:w-full [&_[data-grid-editor]>div]:px-2.5",
  // Inputs (text, number, date) and select triggers. `ring-offset` must be
  // reset too: shadcn's focus ring-offset paints a background-colored halo.
  "[&_[data-grid-editor]_input]:h-full [&_[data-grid-editor]_input]:w-full",
  "[&_[data-grid-editor]_input]:!rounded-none [&_[data-grid-editor]_input]:!border-0",
  "[&_[data-grid-editor]_input]:!bg-transparent [&_[data-grid-editor]_input]:!shadow-none",
  "[&_[data-grid-editor]_input]:!ring-0 [&_[data-grid-editor]_input]:!ring-offset-0",
  "[&_[data-grid-editor]_[role=combobox]]:h-full [&_[data-grid-editor]_[role=combobox]]:w-full",
  "[&_[data-grid-editor]_[role=combobox]]:!rounded-none [&_[data-grid-editor]_[role=combobox]]:!border-0",
  "[&_[data-grid-editor]_[role=combobox]]:!bg-transparent [&_[data-grid-editor]_[role=combobox]]:!shadow-none",
  "[&_[data-grid-editor]_[role=combobox]]:!ring-0 [&_[data-grid-editor]_[role=combobox]]:!ring-offset-0",
  // Checkbox labels repeat the column header, so hide them visually.
  "[&_[data-grid-editor]_label]:sr-only",
].join(" ");

// ── Keyboard navigation ──────────────────────────────────────────────────────

/**
 * Spreadsheet-style focus model: one cell is "active" (focused) and at most one
 * is "editing" (its control is interactive). The last column holds each row's
 * remove button, which Enter and Space press like any button. Focus moves are
 * requested through a ref and applied once the target cell has rendered.
 */
function useGridKeyboard(rowCount: number, columnCount: number) {
  const tableRef = React.useRef<HTMLTableElement>(null);
  const pendingFocus = React.useRef<{
    cell: Cell;
    edit: boolean;
    character?: string;
  } | null>(null);
  const [active, setActive] = React.useState<Cell | null>(null);
  const [editing, setEditing] = React.useState<Cell | null>(null);
  const actionColumn = columnCount - 1;

  React.useLayoutEffect(() => {
    const request = pendingFocus.current;
    const element = request
      ? tableRef.current?.querySelector<HTMLElement>(
          `[data-grid-cell="${request.cell.row}:${request.cell.column}"]`,
        )
      : null;
    // A new row may not have rendered yet; keep the request until it has.
    if (!request || !element) return;
    pendingFocus.current = null;
    const editor = request.edit
      ? element.querySelector<HTMLElement>(EDITOR_SELECTOR)
      : null;
    if (!editor) return element.focus();
    editor.focus();
    // Enter "presses" the control: opens a select, toggles a checkbox.
    if (request.character === undefined) editor.click();
    else typeInto(editor, request.character);
  });

  const focusCell = (cell: Cell) => {
    setEditing(null);
    setActive(cell);
    pendingFocus.current = { cell, edit: false };
  };

  const startEditing = (cell: Cell, character?: string) => {
    setActive(cell);
    setEditing(cell);
    pendingFocus.current = { cell, edit: true, character };
  };

  const moveByTab = (cell: Cell, back: boolean) => {
    const next = tabTarget(cell, rowCount, columnCount, back);
    if (next) focusCell(next);
    return next !== null;
  };

  /**
   * AutoForm's boolean field submits the form on Enter. Inside the grid,
   * Enter on a checkbox only leaves edit mode.
   */
  const onKeyDownCapture = (event: React.KeyboardEvent) => {
    if (!editing || event.key !== "Enter") return;
    if (!(event.target instanceof Element)) return;
    if (!event.target.closest("[role='checkbox']")) return;
    event.preventDefault();
    event.stopPropagation();
    focusCell(editing);
  };

  const onKeyDown = (event: React.KeyboardEvent) => {
    if (!(event.target instanceof Element)) return;
    if (!event.target.closest("[data-grid-cell]")) return;

    if (editing) {
      const commitsInput =
        event.key === "Enter" && event.target instanceof HTMLInputElement;
      if (event.key === "Escape" || commitsInput) {
        event.preventDefault();
        focusCell(editing);
      } else if (event.key === "Tab") {
        if (moveByTab(editing, event.shiftKey)) event.preventDefault();
        else setEditing(null);
      }
      return;
    }
    if (!active) return;

    const move = ARROW_MOVES[event.key];
    if (move) {
      event.preventDefault();
      focusCell({
        row: Math.max(0, Math.min(rowCount - 1, active.row + move[0])),
        column: Math.max(0, Math.min(columnCount - 1, active.column + move[1])),
      });
    } else if (event.key === "Home" || event.key === "End") {
      event.preventDefault();
      const column = event.key === "Home" ? 0 : columnCount - 1;
      focusCell({ row: active.row, column });
    } else if (event.key === "Tab") {
      if (moveByTab(active, event.shiftKey)) event.preventDefault();
    } else if (active.column === actionColumn) {
      // Let the remove button handle Enter and Space natively.
    } else if (event.key === "Enter") {
      event.preventDefault();
      startEditing(active);
    } else if (isPrintableKey(event)) {
      event.preventDefault();
      // Space toggles a checkbox; any other key starts typing a new value.
      startEditing(active, event.key === " " ? undefined : event.key);
    }
  };

  return {
    tableRef,
    active,
    editing,
    setActive,
    setEditing,
    focusCell,
    startEditing,
    onKeyDown,
    onKeyDownCapture,
  };
}

// ── Array wrapper ────────────────────────────────────────────────────────────

/**
 * Lays out an array of objects as an editable table. This is the TanStack Form
 * version; set it on one array with
 * `fieldConfig({ arrayWrapper: ArrayTableWrapper })`.
 *
 * AutoForm still owns the array: it creates the rows (with stable keys and
 * their remove handlers), adds items with the schema defaults and validates
 * them. This wrapper only changes the layout. Instead of each row's generated
 * object field, it renders one cell per column with the AutoForm component
 * registered for that column's type.
 *
 * Limitations: columns should be scalar fields (text, number, date, select,
 * boolean). Because the generated row field is not rendered, errors on the row
 * object itself (e.g. a `.refine()` on the item schema) and per-field wrapper
 * overrides of the columns are not shown. Invalid cells are outlined in red with
 * their message shown inline, and AutoForm's focus-on-submit lands on the first
 * invalid cell (cell controls stay `inert` until a cell is edited).
 */
export function ArrayTableWrapper({
  label,
  error,
  children,
  onAddItem,
  inputProps,
  parsedField,
}: ArrayWrapperProps) {
  const { ref, "aria-invalid": ariaInvalid } = inputProps;
  // The wrapper renders inside the array's own field, whose name is the
  // array's TanStack path (e.g. `team[0].services`).
  const path = useFieldContext()
    .name.replace(/\[(\d+)\]/g, ".$1")
    .split(".");
  const rows = React.Children.toArray(children).filter(
    React.isValidElement<ArrayElementWrapperProps>,
  );
  const columns = parsedField.schema?.[0]?.schema ?? [];
  // The last grid column holds each row's remove button.
  const grid = useGridKeyboard(rows.length, columns.length + 1);
  const addButtonRef = React.useRef<HTMLButtonElement>(null);

  const addRow = () => {
    onAddItem();
    grid.focusCell({ row: rows.length, column: 0 });
  };

  // Keep focus in the table: on the next row's remove button, or on
  // "Add row" once the table is empty.
  const removeRow = (row: ArrayElementWrapperProps, rowIndex: number) => {
    row.onRemove();
    if (rows.length === 1) {
      grid.setActive(null);
      addButtonRef.current?.focus();
    } else {
      const next = Math.min(rowIndex, rows.length - 2);
      grid.focusCell({ row: next, column: columns.length });
    }
  };

  return (
    <div className="not-prose space-y-3">
      <div className="space-y-1">
        {/* AutoForm focuses this heading when the array itself is invalid. */}
        <h3
          ref={ref}
          tabIndex={-1}
          aria-invalid={ariaInvalid}
          className="text-sm font-medium outline-none"
        >
          {label}
          {parsedField.required && <span className="text-destructive"> *</span>}
        </h3>
        {error && <p className="text-sm text-destructive">{error}</p>}
      </div>

      <div
        className={cn(
          "overflow-x-auto rounded-lg border",
          error && "border-destructive",
          "has-[td[aria-invalid=true]]:border-destructive",
        )}
      >
        <table
          ref={grid.tableRef}
          role="grid"
          aria-label={labelText(parsedField)}
          className={cn("w-full text-sm", GRID_STYLES)}
          onKeyDownCapture={grid.onKeyDownCapture}
          onKeyDown={grid.onKeyDown}
        >
          <thead className="bg-muted/40">
            <tr className="border-b">
              {columns.map((column) => (
                <th
                  key={column.key}
                  scope="col"
                  className="px-3 py-2 text-left font-medium"
                >
                  {getLabel(column)}
                </th>
              ))}
              <th scope="col" className="w-10">
                <span className="sr-only">Actions</span>
              </th>
            </tr>
          </thead>
          <tbody>
            {rows.map((row, rowIndex) => (
              <tr key={row.key}>
                {columns.map((column, columnIndex) => (
                  <ArrayTableCell
                    key={column.key}
                    grid={grid}
                    cell={{ row: rowIndex, column: columnIndex }}
                    column={column}
                    path={[...path, String(row.props.index), column.key]}
                  />
                ))}
                <td role="gridcell" className="border-b p-0">
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    data-grid-cell={`${rowIndex}:${columns.length}`}
                    tabIndex={
                      isSameCell(grid.active, {
                        row: rowIndex,
                        column: columns.length,
                      })
                        ? 0
                        : -1
                    }
                    className="h-9 w-full rounded-none text-muted-foreground outline-none hover:text-destructive focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring"
                    aria-label={`Remove row ${rowIndex + 1}`}
                    onFocus={() =>
                      grid.setActive({ row: rowIndex, column: columns.length })
                    }
                    onClick={() => removeRow(row.props, rowIndex)}
                  >
                    <Trash2 />
                  </Button>
                </td>
              </tr>
            ))}
            {rows.length === 0 && (
              <tr>
                <td
                  colSpan={columns.length + 1}
                  className="px-3 py-6 text-center text-muted-foreground"
                >
                  No rows yet.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      <Button
        ref={addButtonRef}
        type="button"
        variant="outline"
        size="sm"
        onClick={addRow}
      >
        <Plus />
        Add row
      </Button>
    </div>
  );
}

// ── Cell ─────────────────────────────────────────────────────────────────────

type GridState = ReturnType<typeof useGridKeyboard>;

/** One grid cell around the column's AutoForm component. */
function ArrayTableCell({
  grid,
  cell,
  column,
  path,
}: {
  grid: GridState;
  cell: Cell;
  column: ParsedField;
  path: string[];
}) {
  // Each cell is its own TanStack field. Providing it through `fieldContext`
  // lets the column's AutoForm component call `useFieldContext` as usual.
  const id = path.join(".");
  const { form } = useFieldContext();
  const cellField = useField({ form, name: formatTanStackPath(path) });
  const error = getErrorMessage(cellField);
  const { formComponents, uiComponents } = useAutoForm();
  const errorId = React.useId();
  const label = labelText(column);
  const active = isSameCell(grid.active, cell);
  const editing = isSameCell(grid.editing, cell);
  // Before any cell is active, the first cell is the grid's Tab stop.
  const isTabStop = grid.active
    ? active && !editing
    : cell.row === 0 && cell.column === 0;
  const FieldComponent: React.ComponentType<AutoFormFieldProps> | undefined =
    formComponents[column.type] ?? formComponents.fallback;

  return (
    <fieldContext.Provider value={cellField}>
      <td
        role="gridcell"
        data-grid-cell={`${cell.row}:${cell.column}`}
        tabIndex={isTabStop ? 0 : -1}
        aria-label={label}
        aria-invalid={Boolean(error) || undefined}
        aria-describedby={error ? errorId : undefined}
        className={cn(
          "border-b border-r p-0 align-middle outline-none",
          error
            ? "bg-destructive/10 ring-2 ring-inset ring-destructive"
            : active && "ring-2 ring-inset ring-ring",
        )}
        onFocus={() => {
          if (!editing) grid.setActive(cell);
        }}
        onBlur={(event) => {
          // Leave edit mode once focus leaves the cell, unless it moved into the
          // control's own popup (e.g. an open select).
          const { currentTarget, relatedTarget } = event;
          const popupOpen = currentTarget.querySelector(
            "[aria-expanded='true']",
          );
          if (editing && !popupOpen && !currentTarget.contains(relatedTarget))
            grid.setEditing(null);
        }}
        onPointerDown={(event) => {
          if (editing) return;
          event.preventDefault();
          grid.startEditing(cell);
        }}
      >
        <div data-grid-editor inert={!editing}>
          {FieldComponent ? (
            <FieldComponent
              path={path}
              id={id}
              error={error}
              parsedField={column}
              label={getLabel(column)}
              inputProps={{
                ...column.fieldConfig?.inputProps,
                "aria-label": label,
                "aria-invalid": Boolean(error) || undefined,
              }}
            />
          ) : (
            <uiComponents.ErrorMessage
              error={`No component found for type "${column.type}"`}
            />
          )}
        </div>
        {error && (
          <p id={errorId} className="px-2.5 pb-1.5 text-xs text-destructive">
            {error}
          </p>
        )}
      </td>
    </fieldContext.Provider>
  );
}
